uint32_t card_fold(uint32_t cp)
{
    size_t lo = 0, hi = sizeof kFold / sizeof kFold[0];
    while (lo < hi) {
        const size_t mid = (lo + hi) / 2;
        if (kFold[mid][0] < cp)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo < sizeof kFold / sizeof kFold[0] && kFold[lo][0] == cp ? kFold[lo][1] : 0;
}

